def calcular_iva_existente(apps, schema_editor):
    """Las facturas anteriores también muestran su IVA (los precios ya lo incluían)."""
    Factura = apps.get_model("caja", "Factura")
    porcentaje = Decimal(settings.IVA_PORCENTAJE)
    for f in Factura.objects.all().only("pk", "total_local"):
        base = (f.total_local / (1 + porcentaje / 100)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        Factura.objects.filter(pk=f.pk).update(iva_porcentaje=porcentaje, base_imponible_local=base, iva_local=f.total_local - base)


